CREATE OR REPLACE FUNCTION udb_authn.assert_api_key_hash()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.key_hash IS NULL OR length(NEW.key_hash) > 128 THEN
    RAISE EXCEPTION 'api_keys.key_hash must be a keyed digest no longer than 128 characters';
  END IF;
  RETURN NEW;
END;
$$;

